  query<T extends QueryResultRow = QueryResultRow>(
    text: string,
    params?: ReadonlyArray<unknown>
  ): Promise<QueryResult<T>>;
  /** Return the client to the pool (pg) / no-op (PGlite). */
  release(): void;
}

